"""Curated design decisions. Names describe responsibilities; no runtime dependency added."""
FW=['svelte','react','vue','angular']
P={}
def pkg(short,layer,scope,why,deps=(),subpaths=(),reuse='',proof='',existing=False,env='TypeScript agnostique, import sans DOM',third=()):
 name='@sentropic/'+short
 P[name]={'name':name,'layer':layer,'scope':scope,'name_rationale':why,'dependencies':['@sentropic/'+d for d in deps],'subpaths':list(subpaths),'reuse':reuse,'acceptance':proof,'existing_name':existing,'environment':env,'third_party_dependencies':list(third),'version_policy':'SemVer indépendant ; tag '+short+'@<version> ; matrice de compatibilité D6 ; aucun tag v* global','dist_tag':'next tant que qualification incomplète, latest après gates propres au package'}
pkg('graph-model','contrats & noyau','Document sémantique typé, entités et relations de première classe, vues, occurrences, références, révisions ; projections de calcul ; AST/CST et provenance par références ; commandes/transactions et validation commune humain-agent ; ports persistence/ressources/présence.','model désigne les identités et invariants sémantiques ; ni géométrie ni widgets.',subpaths=['document','views','references','commands','projection','source','ports'],reuse='Contrats graph/types.ts et dataviz/model.ts comme entrées de compatibilité ; ne pas assimiler Row ou HighLevelGraphInput au nouveau Document.',proof='Références pendantes, relation→relation, occurrences multiples, validation profil, transactions et migrations testées sans DOM.')
