pkg('graph-scene','scène & géométrie','Scène commune, routes et labels calculés, ports, glyphes, buffers, caméra, transformations, spatial index/picking, métriques et transitions géométriques.','scene représente la géométrie prête à peindre, distincte du modèle sémantique.',deps=['graph-model'],subpaths=['scene','geometry','camera','picking','buffers','text','animation'],reuse='graph/{buffers,positions,styles,shape-geometry,render-geometry,edge-geometry,mat4,gitflow-labels}.ts ; helpers DS.',proof='Même identité et géométrie pour SVG/WebGL/DOM/Canvas2D ; picking indépendant backend, tolérances chiffrées ; métriques injectables.')
pkg('graph-codecs','domaines & codecs','Parse/serialize modèles et sources : JSON document, Mermaid, PlantUML/UML, BPMN XML+DI, ArchiMate Exchange, draw.io/mxGraph, Sparx EA XMI par dialecte, Visio VSDX, DOT/xdot, GraphML, Obsidian Canvas, Cypher/GoogleSQL et XML/ZIP sans réseau implicite. Rapports de conversion et conservation AST/CST/extensions.','codecs nomme les conversions bidirectionnelles qualifiées ; exporter une image appartient à graph-export.',deps=['graph-model','graph-profiles','graph-scene'],subpaths=['json','mermaid','plantuml','bpmn','archimate','drawio','xmi','visio','dot','graphml','obsidian','database-scripts','xml','source-map'],reuse='Sérialisations Sentropic existantes comme fixtures/compat ; aucune lib de parser tierce implicitement transportée.',proof='Sous-ensembles documentés par dialecte/version, pertes localisées ; cycle parse/serialize et fixtures hostiles ; aucun round-trip universel promis.')
pkg('graph-processing','processing','Parcours, composantes, tri topologique, chemins (Dijkstra), sous-graphes, agrégation et projections de graphe ; diagnostics structurels pour les layouts.','processing traite la topologie et les données, sans promettre des coordonnées ; sépare les chemins analytiques du routage visuel.',deps=['graph-model'],subpaths=['traversal','components','paths','projection','constraints'],reuse='Extraire uniquement helpers génériques Sentropic ; graphology/Louvain de retrieval restent dans graphify.',proof='Résultats topologiques et cas cycles/multigraphes vérifiés ; provenance conservée ; 0 dependency de renderer.')
pkg('graph-routing','processing / routage','Chemins visuels orthogonaux, octilinéaires, segments, courbes, évitement obstacles, ports/ancres, buses, hyperarêtes, link-to-link, self-loops, labels.','routing distingue les trajectoires dessinées des chemins analytiques et du placement de nœuds.',deps=['graph-model','graph-scene'],subpaths=['orthogonal','octilinear','curves','obstacles','ports','labels','bundles'],reuse='graph/{render-geometry,edge-geometry}.ts, DS arêtes SVG ; comparaison libavoid/Graphviz sans dépendance.',proof='Obstacles, clearance, extrémités, ports, labels et impossibles diagnostiqués ; géométrie commune aux backends.')
pkg('graph-layout','processing / placement','Registre et phases de placement, les 21 références ELK et 10 entrées Graphviz, leurs groupes/options, layouts graphify et DS ; layered, arbres, radial/circulaire, force/stress, grilles, packing/compaction/overlap ; seed/incrémental/contraintes.','layout a un contrat géométrique unique ; familles et variantes en sous-chemins, aucun package par algorithme fournisseur.',deps=['graph-model','graph-processing','graph-scene','graph-routing'],subpaths=['registry','layered','tree','radial','force','stress','grid','packing','compaction','fixed','random','domain'],reuse='graph/layout*.ts ; graphify/src/{graph-layout,hierarchy-layout}.ts ; simulations DS ForceGraph et layouts charts.',proof='Chaque ID/options reference possède fixture et statut ; résultat positions/rects/ports/routes/labels/diagnostics ; déterminisme ≠ stabilité incrémentale ; compat PositionFrame explicite.')
pkg('graph-worker','moteurs / exécution','Protocole de jobs sur snapshots révisionnés, transfert buffers, progrès, annulation, timeout, choix de moteur, rejet résultats périmés et fallback synchrone.','worker nomme le mode d’exécution ; ne présente pas le transport comme un nouvel algorithme.',deps=['graph-model','graph-scene','graph-layout'],subpaths=['protocol','browser','synchronous'],reuse='graphify/studio/src/lib/{layoutWorker,forceLayoutClient}.js ; supprimer alias Vite privé après bascule.',proof='Révision document+vue+projection, jobId/generation ; après édition, ancien résultat refusé ; byte-equivalence sync/worker ; aucun global Worker à import.')
pkg('graph-compiler','compilation','Compilateur unique document/profil/vue → projection, plan de processing et scène/contrats interaction ; métriques texte/image et moteurs injectables ; sortie sérialisable identique pour les quatre frameworks.','compiler décrit la transformation partagée ; views appartient déjà au modèle. D3 ne signifie ni quatre compilateurs, ni un parseur commun à tous dialectes.',deps=['graph-model','graph-profiles','graph-processing','graph-layout','graph-scene'],subpaths=['compile','projection','diagnostics'],reuse='Séparer le raccord générique des scene-layout/studio-render-buffers/graphRendererPayload ; producteur graph.json reste produit.',proof='Un corpus et un hash de scène partagé 4-fw ; aucune API DOM/framework ; diagnostics source→entity→occurrence ; aucune dépendance focus-render/Track.')
pkg('graph','moteurs / compatibilité publique','Renderer Sentropic WebGL2 et Canvas2D ; buffers et API historiques préservés, façade délégante vers scene/layout après extraction compatible.','Nom publié @sentropic/graph préservé ; aucune nouvelle marque remplaçant la bibliothèque.',deps=['graph-scene','graph-layout'],subpaths=['.'],reuse='Intégralité packages/graph (211 exports), tests, golden, bench, licence et provenance ; M1 intact avant extraction.',proof='ESM+CJS+types et 211 exports conservés ; goldens Canvas2D/WebGL ; canari WebGL et fallback restent visibles.',existing=True,env='Backend navigateur WebGL2/Canvas2D ; helpers purs ; import sans instanciation browser à qualifier')
pkg('graph-svg','moteurs de rendu','Peinture SVG de la scène, sérialisation vectorielle, DOM SVG interactif, marqueurs, texte, clip/mask/gradients, images ; support SSR sérialisé.','svg désigne le backend, pas une variante du document ou un codec métier.',deps=['graph-scene'],subpaths=['serialize','dom'],reuse='shapeSvgPath et render-geometry graph ; primitives SVG DS, adaptation sans recopier les composants.',proof='Parité géométrique avec graph ; styles/tokens résolus, font metrics identiques, lien occurrence→element et snapshot SVG.')
pkg('graph-dom','moteurs de rendu','Nœuds HTML-DOM, formulaires, texte/IME, measurements ; composition hybride avec layer arêtes SVG ou WebGL fourni par port, coords/caméra/focus synchronisés.','dom dit explicitement que le backend travaille sur éléments HTML ; HTML ne fournit pas implicitement le routage des arêtes.',deps=['graph-scene'],subpaths=['nodes','measure','hybrid'],reuse='Contrôles DS existants et GraphCanvas Svelte ; rendu HTML générique nouveau à qualifier.',proof='resize/zoom/scroll, arêtes cross-layer, IME/focus/clavier et SSR placeholder, CSP qualifiée ; aucun framework intégré.',env='DOM navigateur ; contrat importable sans document')
pkg('graph-canvas','interaction & canvas','Contrôleur headless sélection, déplacements/redim/rotation, ports/liens, snap/guides/groupes, clipboard, undo-redo, annotations/cerclage, viewport, outils, modes ; commandes validées et ports de persistence/présence.','canvas signifie surface de travail éditable multi-backend ; ne force ni Canvas2D ni état BI.',deps=['graph-model','graph-scene','graph-processing','graph-routing'],subpaths=['controller','commands','tools','clipboard','history','annotations','viewport'],reuse='Gestes GraphCanvas, sélection renderer à extraire vers scene, DiagramAnnotator (ellipse/rect/PNG) ; UI générique via DS.',proof='preview/transaction/persistence distincts ; humains/agents mêmes validations ; undo atomique et conflicts révision ; aucun verrou déduit h2a/Track.')
pkg('graph-export','artefacts / exports','Plan d’export scène, ressources/fonts, SVG/raster/PDF/PPTX/HTML/print, sorties Graphviz et surfaces terminal/native explicitement typées ; page/tile/scale et rapport de fidélité. JSON document délégué au codec ; données CSV à dataviz-core.','export nomme les artefacts livrables distincts de la conversion sémantique ; sous-chemins évitent un package par extension.',deps=['graph-model','graph-scene','graph-svg','graph-codecs'],subpaths=['plan','svg','raster','pdf','pptx','html','print','graphviz','terminal','native-surfaces'],reuse='dataviz-*/lib/chart-export.ts et DiagramAnnotator.toPNG ; maintenir les façades historiques.',proof='SVG/PNG/PDF/print régressions ; PPTX slides/médias/éditabilité explicites ; aucune sortie silencieusement substituée ; pixels vs objets vs sémantique tracés.',env='Plan pur ; /raster,/print browser ; encodeurs isolés/lazy',third=['jspdf ^4.2.1 et svg2pdf.js ^2.7.0 : continuité des imports PDF dataviz existants ; isoler sous /pdf, ne pas importer depuis la racine. Versions finales pins D6 à qualifier. Aucune autre dependency nouvelle autorisée.'])
