# Official feature labels map to behavior owners, not to vendor dependencies.
FEATURE_OWNERS={}
def features(owner,labels):
 for label in labels.split('|'):FEATURE_OWNERS[label]=owner
features('graph-canvas','Adjustable interactivity|Collapse & Expand|Constraints on movement|Copy & Paste|Drag & Drop|Element palette|Element tools|Events|Grid|Guidelines|Keyboard|Link tools|Minimap|Property editor & viewer|Selection|Shape transformation|Toggle visibility|Undo/Redo|Zoom & Pan|Save/Load')
features('graph-scene','Animation|Content-driven shapes|Custom shapes|External images|Geometry|Highlighters|Measurement|Text content|Vectorizer|Virtual rendering|Performance')
features('graph-routing','Anchors|Connection points|Connectors|Link labels|Link-to-link|Ports|Routers')
features('graph-model','Custom properties|Embedding|Graph API|Validation')
features('graph-layout','Automatic layout')
features('graph-profiles','Built-in shapes')
features('graph-codecs','Export to JSON|Import/Export|Visio')
features('graph-export','Export to PDF|Export to PNG/JPEG|Export to SVG|Print')
features('graph-dom','HTML shapes')
features('graph-recipes','Simulation|Integration')
# Visual UI feature owner = concrete adapter; framework peers contribute equally.
features('graph-svelte','CSS styling|Context Toolbar|Menus|Popups|Responsive|Toolbar|Tooltips')

